// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(uint256(uint160(actor)) != 0x10000);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 1 ether}(t);
        uint256 expected = t > block.timestamp ? t : block.timestamp;
        (uint256 unlockTime,) = c.Acc(actor);
        assertTrue(unlockTime == expected);
    }
}
